// The Cyrus tables that move to Cyrus' own database. Derived, never hand-listed: every model in the CyrusDb type
// (lib/cyrus/host/types.ts: what cyrusDb may touch) plus the SQL-only Cyrus tables in prisma manual migrations, minus
// the tables that belong to Nxeon's side of the bridge.   node tables.mjs [--json]
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
/** Nxeon-side tables: the receiver of Cyrus' webhooks lives in Nxeon (lib/cyrus-client/webhook-receiver.ts). */
export const NXEON_SIDE = new Set(["CyrusWebhookReceipt"]);

export function cyrusTables(root = ROOT) {
  const types = readFileSync(path.join(root, "lib/cyrus/host/types.ts"), "utf8");
  const pick = /export type CyrusDb = Pick<PrismaClient,([\s\S]*?)>;/.exec(types);
  if (!pick) throw new Error("CyrusDb Pick<> not found in lib/cyrus/host/types.ts");
  const models = [...pick[1].matchAll(/"([a-zA-Z]+)"/g)].map((m) => m[1]).filter((m) => !m.startsWith("$"))
    .map((m) => m[0].toUpperCase() + m.slice(1));
  const schema = readFileSync(path.join(root, "prisma/schema.prisma"), "utf8");
  for (const m of models) if (!new RegExp(`^model ${m} \\{`, "m").test(schema)) throw new Error(`CyrusDb names ${m} but schema.prisma has no such model`);
  const sqlFiles = [
    ...readdirSync(path.join(root, "prisma")).filter((f) => f.endsWith(".sql")).map((f) => path.join(root, "prisma", f)),
    ...readdirSync(path.join(root, "prisma/manual-migrations")).filter((f) => f.endsWith(".sql")).map((f) => path.join(root, "prisma/manual-migrations", f)),
  ];
  const sqlOnly = new Set();
  for (const f of sqlFiles) for (const m of readFileSync(f, "utf8").matchAll(/CREATE TABLE (?:IF NOT EXISTS )?"(Cyrus[A-Za-z]+)"/g)) sqlOnly.add(m[1]);
  const all = new Map(models.map((m) => [m, "prisma"]));
  for (const t of sqlOnly) if (!all.has(t)) all.set(t, "sql-only");
  for (const t of NXEON_SIDE) all.delete(t);
  return [...all].sort(([a], [b]) => a.localeCompare(b)).map(([name, source]) => ({ name, source }));
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const t = cyrusTables();
  if (process.argv.includes("--json")) console.log(JSON.stringify(t, null, 2));
  else t.forEach((x) => console.log(x.name));
}
