  const h = rows.length * rowH + 4;
  return (
    <svg viewBox={`0 0 ${w} ${h}`} width="100%" role="img" aria-label="Wizard funnel: actors reaching each step" style={{ maxHeight: h }}>
      {rows.map((r, i) => {
        const y = i * rowH + 2;
