/**
 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
 * These are read-only Prisma queries over the `Visit` table. Everything is
 * scoped to short recent windows and small `take` limits so the page stays
 * cheap even as the visit log grows.
 */

const DAY = 86_400_000;

// Indochina Time (ICT) is a fixed UTC+7 offset with no DST, so this never needs
// a real tz database — every "today" figure on the visitor-analytics page
// anchors to ICT midnight rather than the server process's own local
// timezone, so the number an admin in Bangkok/Saigon/Jakarta reads as "today"
// matches the day they're actually in, regardless of what timezone this box
// happens to be running in.
const ICT_OFFSET_MS = 7 * 60 * 60 * 1000;

/** The UTC instant of the most recent ICT midnight (00:00 ICT) at or before `now`. */
export function startOfTodayICT(now: Date = new Date()): Date {
  const shifted = new Date(now.getTime() + ICT_OFFSET_MS);
  shifted.setUTCHours(0, 0, 0, 0);
  return new Date(shifted.getTime() - ICT_OFFSET_MS);
}

/** IPs the admin has chosen to exclude from analytics (their own IP, office IP,
 *  a noisy bot) so the numbers reflect ACTUAL public traffic. Stored as a
 *  comma-separated setting. */
export async function excludedIps(): Promise<string[]> {
  const raw = (await getSetting("analytics_excluded_ips")) ?? "";
  return raw.split(",").map((s) => s.trim()).filter(Boolean);
}

/** Prisma where-fragment every visitor-analytics read spreads into its `where`:
 *  drops the admin's excluded IPs AND bot traffic (`isBot = false`, see
 *  lib/bots/*). Bots are excluded by default; the admin "include bots" toggle
 *  (cookie, lib/bots/scope.ts) lifts only the bot filter, never the IP list.
 *  Outside a request (worker rollups) bots are always excluded. */
async function ipEx(): Promise<{ ip?: { notIn: string[] }; isBot?: boolean }> {
  const [e, bots] = await Promise.all([excludedIps(), botWhere()]);
  return { ...(e.length ? { ip: { notIn: e } } : {}), ...bots };
}

/** Public alias of the shared visitor scope, for other analytics modules
 *  (lib/insights/*, lib/retention.ts, admin pages querying Visit directly). */
export const visitScope = ipEx;

/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
export async function liveVisitors(minutes = 5): Promise<number> {
  const since = new Date(Date.now() - minutes * 60_000);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Total page views since ICT midnight ("today" for this page — see startOfTodayICT). */
export async function todayViews(): Promise<number> {
  const start = startOfTodayICT();
  return db.visit.count({ where: { createdAt: { gte: start }, ...(await ipEx()) } });
}

/** Distinct visitors (by IP) since ICT midnight. */
export async function uniqueVisitorsToday(): Promise<number> {
  const start = startOfTodayICT();
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: start }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Total page views in the trailing `days` window (default 7d). */
export async function viewsInWindow(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  return db.visit.count({ where: { createdAt: { gte: since }, ...(await ipEx()) } });
}

/** Distinct visitors (by IP) in the trailing `days` window. */
export async function uniqueVisitors(days = 7): Promise<number> {
